from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    comp = [[-1] * w for _ in range(h)]
    colors = {}
    cid = 0
    # Components are the separate 4-connected non-background figures.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or comp[r][c] >= 0:
                continue
            q = deque([(r, c)])
            comp[r][c] = cid
            while q:
                y, x = q.popleft()
                if grid[y][x] not in (0, 1):
                    colors[cid] = grid[y][x]
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and comp[yy][xx] < 0:
                        comp[yy][xx] = cid
                        q.append((yy, xx))
            cid += 1
    # A colored cell is an example of a 3x3 all-foreground pattern.
    # Recolor the center of every matching 3x3 window in its figure.
    for y in range(1, h-1):
        for x in range(1, w-1):
            if grid[y][x] not in (0, 1):
                continue
            k = comp[y][x]
            if k in colors and all(grid[yy][xx] != 0 and comp[yy][xx] == k
                                   for yy in range(y-1, y+2) for xx in range(x-1, x+2)):
                out[y][x] = colors[k]
    return out
